import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Send, AlertTriangle, ShieldCheck, ShieldAlert } from "lucide-react";
import { checkFraud, INDIAN_CITIES, type Transaction } from "@/lib/fraud-engine";
import GlassCard from "./GlassCard";

const BEHAVIOR_OPTIONS = [
  "Normal activity",
  "new device",
  "multiple failed attempts",
  "unusual hours",
  "rapid transactions",
  "location change",
  "otp sharing",
  "unknown upi id",
];

interface TransactionFormProps {
  onSubmit: (tx: Transaction) => void;
}

const statusConfig = {
  safe:        { Icon: ShieldCheck,    color: "text-success",     bg: "bg-success/10",     label: "Transaction Safe" },
  suspicious:  { Icon: AlertTriangle,  color: "text-warning",     bg: "bg-warning/10",     label: "Suspicious Activity" },
  fraud:       { Icon: ShieldAlert,    color: "text-destructive", bg: "bg-destructive/10", label: "Fraud Detected!" },
} as const;

export default function TransactionForm({ onSubmit }: TransactionFormProps) {
  const [amount, setAmount] = useState("");
  const [location, setLocation] = useState("");
  const [behavior, setBehavior] = useState("");
  const [result, setResult] = useState<{ score: number; status: keyof typeof statusConfig } | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setResult(null);
    setTimeout(() => {
      const time = new Date().toISOString();
      const res = checkFraud({ amount: parseFloat(amount), location, time, userBehavior: behavior });
      setResult(res);
      const tx: Transaction = {
        id: `TXN-${Date.now()}`,
        userId: `USR-${Math.floor(Math.random() * 100) + 1}`,
        amount: parseFloat(amount),
        location,
        timestamp: time,
        fraudScore: res.score,
        isFraud: res.status === "fraud",
        status: res.status,
      };
      onSubmit(tx);
      setLoading(false);
    }, 900);
  };

  return (
    <GlassCard delay={0.2} hover={false} className="max-w-2xl mx-auto">
      <h2 className="text-xl font-display font-bold mb-6 text-gradient">Analyze Transaction</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-sm text-muted-foreground mb-1 block">Amount (₹)</label>
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              required
              min="0"
              step="0.01"
              placeholder="e.g. 50000"
              className="w-full px-4 py-3 rounded-lg bg-input border text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
            />
          </div>
          <div>
            <label className="text-sm text-muted-foreground mb-1 block">Location</label>
            <select
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              required
              className="w-full px-4 py-3 rounded-lg bg-input border text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
            >
              <option value="">Select city</option>
              {INDIAN_CITIES.map((city) => (
                <option key={city} value={city}>{city}</option>
              ))}
              <option value="VPN">VPN / Anonymous</option>
              <option value="Unknown">Unknown Location</option>
            </select>
          </div>
        </div>
        <div>
          <label className="text-sm text-muted-foreground mb-1 block">User Behavior</label>
          <select
            value={behavior}
            onChange={(e) => setBehavior(e.target.value)}
            className="w-full px-4 py-3 rounded-lg bg-input border text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all"
          >
            <option value="">Select behavior</option>
            {BEHAVIOR_OPTIONS.map((b) => (
              <option key={b} value={b}>{b.charAt(0).toUpperCase() + b.slice(1)}</option>
            ))}
          </select>
        </div>


        <motion.button
          type="submit"
          disabled={loading}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          className="w-full py-3 rounded-lg gradient-primary text-primary-foreground font-semibold flex items-center justify-center gap-2 disabled:opacity-50 transition-all"
        >
          {loading ? (
            <motion.div
              animate={{ rotate: 360 }}
              transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
              className="w-5 h-5 border-2 border-primary-foreground/30 border-t-primary-foreground rounded-full"
            />
          ) : (
            <>
              <Send size={18} /> Check Transaction
            </>
          )}
        </motion.button>
      </form>

      <AnimatePresence>
        {result && (() => {
          const cfg = statusConfig[result.status];
          const Icon = cfg.Icon;
          return (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              className="mt-6 overflow-hidden"
            >
              <motion.div
                initial={{ scale: 0.92 }}
                animate={{ scale: 1 }}
                className={`p-5 rounded-lg ${cfg.bg} border flex items-center gap-4`}
              >
                <Icon className={`${cfg.color} flex-shrink-0`} size={32} />
                <div>
                  <p className={`font-display font-bold text-lg ${cfg.color}`}>{cfg.label}</p>
                  <p className="text-sm text-muted-foreground">
                    Fraud Score: <span className="font-mono font-bold text-foreground">{result.score}%</span>
                  </p>
                </div>
                <div className="flex-1 ml-4">
                  <div className="h-2 bg-muted rounded-full overflow-hidden">
                    <motion.div
                      initial={{ width: 0 }}
                      animate={{ width: `${result.score}%` }}
                      transition={{ duration: 0.8, ease: "easeOut" }}
                      className={`h-full rounded-full ${
                        result.status === "fraud" ? "gradient-danger" : result.status === "suspicious" ? "bg-warning" : "bg-success"
                      }`}
                    />
                  </div>
                </div>
              </motion.div>
            </motion.div>
          );
        })()}
      </AnimatePresence>
    </GlassCard>
  );
}
