import { motion } from "framer-motion";
import type { Transaction } from "@/lib/fraud-engine";

const statusBadge: Record<Transaction["status"], string> = {
  safe: "bg-success/15 text-success border-success/25",
  suspicious: "bg-warning/15 text-warning border-warning/25",
  fraud: "bg-destructive/15 text-destructive border-destructive/25",
};

export default function TransactionTable({ transactions }: { transactions: Transaction[] }) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.6 }}
      className="glass rounded-xl overflow-hidden"
    >
      <div className="p-6 border-b">
        <h3 className="text-lg font-display font-semibold">Recent Transactions</h3>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b">
              {["ID", "Amount", "Location", "Score", "Status", "Time"].map((h) => (
                <th key={h} className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {transactions.slice(0, 10).map((tx, i) => (
              <motion.tr
                key={tx.id}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.3, delay: i * 0.04 }}
                className="border-b hover:bg-muted/30 transition-colors"
              >
                <td className="px-6 py-4 text-sm font-mono">{tx.id}</td>
                <td className="px-6 py-4 text-sm font-semibold">₹{tx.amount.toLocaleString("en-IN")}</td>
                <td className="px-6 py-4 text-sm">{tx.location}</td>
                <td className="px-6 py-4 text-sm font-mono font-bold">{tx.fraudScore}%</td>
                <td className="px-6 py-4">
                  <span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${statusBadge[tx.status]}`}>
                    {tx.status.toUpperCase()}
                  </span>
                </td>
                <td className="px-6 py-4 text-sm text-muted-foreground">
                  {new Date(tx.timestamp).toLocaleDateString("en-IN")}
                </td>
              </motion.tr>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
}
